import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine input type: adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor list
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]
    # Edge case: no edges
    if all(len(nei) == 0 for nei in neighbors):
        return [0] * n

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if coloring[v] == cu:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Helper: DSATUR heuristic
    def dsatur():
        coloring = [-1] * n
        sat = [0] * n  # saturation degree
        colored = [False] * n
        # Initialize: pick vertex with max degree
        if n == 0:
            return coloring
        degrees = [len(neighbors[i]) for i in range(n)]
        v = max(range(n), key=lambda i: degrees[i])
        coloring[v] = 0
        colored[v] = True
        # Update saturation for neighbors
        for u in neighbors[v]:
            sat[u] += 1
        # Color remaining vertices
        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat:
                        max_sat = sat[i]
                        candidates = [i]
                    elif sat[i] == max_sat:
                        candidates.append(i)
            if max_sat == -1:  # no uncolored vertices (should not happen)
                break
            # Tie-break by degree in uncolored subgraph
            def uncolored_degree(x):
                return sum(1 for y in neighbors[x] if not colored[y])
            v = max(candidates, key=lambda x: (uncolored_degree(x), random.random()))
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] += 1
        return coloring

    # Helper: RLF (Recursive Largest First) heuristic
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        while any(not c for c in colored):
            # Step 1: pick vertex with max degree in uncolored subgraph
            uncolored = [i for i in range(n) if not colored[i]]
            if not uncolored:
                break
            # Compute degrees in uncolored subgraph
            def deg_in_uncolored(v):
                return sum(1 for u in neighbors[v] if not colored[u])
            v = max(uncolored, key=deg_in_uncolored)
            # Initialize independent set S and partitions U, W
            S = [v]
            colored[v] = True
            U = [u for u in uncolored if u != v and u not in neighbors[v]]
            W = [u for u in uncolored if u != v and u in neighbors[v]]
            # Step 2: while U not empty, add vertices to S
            while U:
                # For each u in U, compute |N(u) ∩ W|
                best_u = None
                best_score = -1
                best_deg_in_U = None
                for u in U:
                    # Score: number of neighbors in W
                    score = sum(1 for w in neighbors[u] if w in W)
                    # Tie-break: min degree in U
                    deg_in_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and (best_deg_in_U is None or deg_in_U < best_deg_in_U)):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break  # should not happen
                # Add best_u to S
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        if w not in W:
                            W.append(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring

    # Helper: degeneracy ordering (smallest-last)
    def degeneracy_order():
        # Compute degeneracy ordering via smallest-last
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                buckets[d].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            # Get a vertex from bucket[ptr]
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    # Remove u from its current bucket
                    if d <= max_deg and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
                    # Update ptr if needed
                    if d_new < ptr:
                        ptr = d_new
        # Reverse to get coloring order
        order.reverse()
        return order

    # Try multiple heuristics and keep the best valid coloring
    best_coloring = None
    best_colors = float('inf')

    # 1. DSATUR
    c1 = dsatur()
    if is_valid(c1):
        colors_used = max(c1) + 1 if n > 0 else 0
        if colors_used < best_colors:
            best_colors = colors_used
            best_coloring = c1[:]
    # 2. RLF
    c2 = rlf()
    if is_valid(c2):
        colors_used = max(c2) + 1 if n > 0 else 0
        if colors_used < best_colors:
            best_colors = colors_used
            best_coloring = c2[:]
    # 3. Degeneracy ordering + greedy
    order = degeneracy_order()
    c3 = greedy_color(order)
    if is_valid(c3):
        colors_used = max(c3) + 1 if n > 0 else 0
        if colors_used < best_colors:
            best_colors = colors_used
            best_coloring = c3[:]
    # 4. Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    c4 = greedy_color(order_wp)
    if is_valid(c4):
        colors_used = max(c4) + 1 if n > 0 else 0
        if colors_used < best_colors:
            best_colors = colors_used
            best_coloring = c4[:]
    # 5. Randomized greedy with shuffling (multiple attempts)
    for _ in range(10):
        order_rand = list(range(n))
        random.shuffle(order_rand)
        c5 = greedy_color(order_rand)
        if is_valid(c5):
            colors_used = max(c5) + 1 if n > 0 else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = c5[:]
    # Fallback: if none valid (should not happen), use DSATUR
    if best_coloring is None:
        best_coloring = dsatur()
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Handle single vertex
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            # Ensure we don't include self-loops and handle potential duplicates
            for j in adj[i]:
                if i != j:
                    neighbors[i].add(j)

    # Make the graph undirected (ensure symmetry)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Remove self-loops if any
    for i in range(n):
        if i in neighbors[i]:
            neighbors[i].remove(i)

    # If no edges, all vertices can be color 0
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Compute degeneracy ordering (smallest-last) for initial upper bound
    remaining = set(range(n))
    deg = [len(neighbors[i]) for i in range(n)]
    order = []
    # We'll simulate peeling by repeatedly removing min degree vertex
    # Use a list of sets for buckets for efficiency, but n<=100 so simple scan is fine
    temp_remaining = remaining.copy()
    temp_deg = deg[:]
    stack = []
    while temp_remaining:
        # Find vertex with minimum degree in temp_remaining
        v = min(temp_remaining, key=lambda x: temp_deg[x])
        stack.append(v)
        temp_remaining.remove(v)
        for u in neighbors[v]:
            if u in temp_remaining:
                temp_deg[u] -= 1
    # The reverse of the peel order is the coloring order
    order = stack[::-1]

    # Greedy coloring in the degeneracy order to get initial upper bound
    color = [-1] * n
    for v in order:
        used = [False] * (n + 1)  # n+1 is safe upper bound
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
    # Current number of colors used
    k = max(color) + 1 if n > 0 else 0

    # If k is 1, we already handled edgeless, but just in case
    if k == 1:
        return color

    # Try to improve the coloring using Kempe chain swaps to reduce color count
    # We'll attempt to eliminate the last color (k-1) iteratively
    improved = True
    while improved and k > 1:
        improved = False
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if color[v] == target_color]
        if not target_vertices:
            k -= 1
            continue

        # For each vertex in target color, try to recolor it to a lower color
        for v in target_vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            for c in range(target_color):  # try colors 0 to target_color-1
                if c not in neighbor_colors:
                    # Found a free color, reassign
                    color[v] = c
                    improved = True
                    break
            if improved:
                # After reassigning one vertex, break to restart the elimination check
                break

            # If direct reassignment not possible, try Kempe chains
            for c in range(target_color):
                # We want to see if we can swap colors in the (c, target_color) Kempe chain
                # containing v to free color c for v.
                # Build the Kempe chain component containing v for colors c and target_color
                from collections import deque
                component = set()
                queue = deque([v])
                visited = set([v])
                while queue:
                    node = queue.popleft()
                    component.add(node)
                    for u in neighbors[node]:
                        if u not in visited and (color[u] == c or color[u] == target_color):
                            visited.add(u)
                            queue.append(u)
                # Now, check if any neighbor of v has color c
                # If not, we can swap the component: v will get color c after swap
                has_c_neighbor = False
                for u in neighbors[v]:
                    if color[u] == c:
                        has_c_neighbor = True
                        break
                if not has_c_neighbor:
                    # Swap colors c and target_color in the component
                    for node in component:
                        if color[node] == c:
                            color[node] = target_color
                        elif color[node] == target_color:
                            color[node] = c
                    # Now v has color c (since it was target_color and swapped)
                    improved = True
                    break
            if improved:
                break

        # After attempting to recolor all target vertices, if we improved, we may have reduced k
        if improved:
            # Recompute k as the actual max color + 1
            k = max(color) + 1
        else:
            # Could not eliminate target_color, so we keep it
            break

    # Final validation: ensure coloring is valid (should be, but check for safety)
    for v in range(n):
        for u in neighbors[v]:
            if color[v] == color[u]:
                # In case of error, fallback to greedy coloring with degeneracy order
                color = [-1] * n
                for v in order:
                    used = [False] * (n + 1)
                    for u in neighbors[v]:
                        if color[u] != -1:
                            used[color[u]] = True
                    c = 0
                    while c <= n and used[c]:
                        c += 1
                    color[v] = c
                break

    return color
